const sk = sketch('front', 0)
sk.polygon([[5, 0], [20, 0], [20, 5], [10, 5], [10, 25], [5, 25]])
const part = revolve(sk, 360)
hole(part, { across: 3, at: [15, 0] })
hole(part, { across: 3, at: [-15, 0] })
hole(part, { across: 3, at: [0, 15] })

const b = box(40, 30, 10)
hole(b, { across: 0.1 })
hole(b, { across: 4, at: [10, 5] })

const b = box(40, 30, 10)
round(b.edge('top', 'right'), 12)
hole(b, { across: 4 })

const b = box(40, 30, 10)
round(b.edge('top', 'right'), 12)
hole(b, { across: 4, at: [100, 0] })

const b = box(40, 30, 10)
hole(b, { across: 4 })
hole(b, { across: 4, at: [10, 5] })
